def response_state(state, row, result, mode='full', include_catalog=True):
    result = dict(result)
    if mode == 'battle':
        combat = view(state, False)
        battle = combat.get('battle')
        if battle:
            # Viewers intentionally play only recent feedback; history remains authoritative in storage.
            battle['feedback'] = [f for f in battle.get('feedback', []) if battle['elapsed']-f['at'] <= 1]
        def wire(value):
            if isinstance(value, float): return round(value, 6)
            if isinstance(value, dict): return {k: wire(v) for k, v in value.items()}
            if isinstance(value, list): return [wire(v) for v in value]
            return value
        combat = wire(combat)
        result.update(battleOnly=True, combat={k: combat[k] for k in ('battle', 'locked', 'continuous', 'wave')},
            revision=state['revision'], snapshotSeq=state['snapshotSeq'], serverTime=state['last'])

else:
    result['state'] = snapshot(state, row['id'], row['name'], include_catalog)
return result
